233	func (e *Agent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
234		const maxParseHookBytes = 10 * 1024 * 1024 // 10 MB
235		data, err := io.ReadAll(io.LimitReader(stdin, maxParseHookBytes))
236		if err != nil {
237			return nil, fmt.Errorf("parse-hook: read stdin: %w", err)
238		}
239		stdout, err := e.run(ctx, data, "parse-hook", "--hook", hookName)
240		if err != nil {
241			return nil, fmt.Errorf("parse-hook: %w", err)
242		}
243		// null means no lifecycle significance
244		if bytes.Equal(bytes.TrimSpace(stdout), []byte("null")) {
245			return nil, nil //nolint:nilnil // protocol contract: null = no event
246		}
247		var event eventJSON
248		if err := json.Unmarshal(stdout, &event); err != nil {
249			return nil, fmt.Errorf("parse-hook: invalid JSON: %w", err)
250		}
251		return event.toEvent()
252	}
