422	// run executes a subcommand on the external binary and returns stdout bytes.
423	// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
424	// included in the returned error.
425	func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
426		// Apply a default timeout when the caller hasn't set a deadline, so a hung
427		// external binary can't block the CLI (or git hooks) indefinitely.
428		if _, ok := ctx.Deadline(); !ok {
429			var cancel context.CancelFunc
430			ctx, cancel = context.WithTimeout(ctx, defaultRunTimeout)
431			defer cancel()
432		}
433		cmd := exec.CommandContext(ctx, e.binaryPath, args...)
434		// Ensure I/O goroutines are released shortly after the process is killed,
435		// so cmd.Run() doesn't block waiting for pipe reads.
436		cmd.WaitDelay = 3 * time.Second
437	
438		cmd.Env = append(cmd.Environ(),
439			"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
440			"ENTIRE_CLI_VERSION="+versioninfo.Version,
441		)
442		if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
443			cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
444			cmd.Dir = repoRoot
445		}
446	
447		if stdin != nil {
448			cmd.Stdin = bytes.NewReader(stdin)
449		}
450	
451		const maxOutputBytes = 10 * 1024 * 1024 // 10 MB
452	
453		var stdoutBuf, stderrBuf bytes.Buffer
454		stdoutLW := &limitedWriter{buf: &stdoutBuf, limit: maxOutputBytes}
455		stderrLW := &limitedWriter{buf: &stderrBuf, limit: maxOutputBytes}
456		cmd.Stdout = stdoutLW
457		cmd.Stderr = stderrLW
458	
459		if err := cmd.Run(); err != nil {
460			errMsg := strings.TrimSpace(stderrBuf.String())
461			if errMsg != "" {
462				return nil, fmt.Errorf("%s: %s", args[0], errMsg)
463			}
464			return nil, fmt.Errorf("%s: %w", args[0], err)
465		}
466	
467		if stdoutLW.truncated {
468			return nil, fmt.Errorf("%s: output exceeded %d byte limit", args[0], maxOutputBytes)
469		}
470	
471		return stdoutBuf.Bytes(), nil
472	}
473	
474	// --- Helpers ---
475	
476	// limitedWriter wraps a bytes.Buffer and stops writing after limit bytes,
477	// preventing unbounded memory growth from external process output.
478	type limitedWriter struct {
479		buf       *bytes.Buffer
480		limit     int
481		truncated bool
482	}
483	
484	func (w *limitedWriter) Write(p []byte) (int, error) {
485		remaining := w.limit - w.buf.Len()
486		if remaining <= 0 {
487			w.truncated = true
488			return len(p), nil // discard, but report success so the process isn't killed
489		}
490		if len(p) > remaining {
491			p = p[:remaining]
492			w.truncated = true
493		}
494		n, err := w.buf.Write(p)
495		if err != nil {
496			return n, fmt.Errorf("writing to limited buffer: %w", err)
497		}
498		return n, nil
499	}
