501	func marshalHookInput(input *agent.HookInput) ([]byte, error) {
502		if input == nil {
503			return []byte("{}"), nil
504		}
505		j := HookInputJSON{
506			HookType:   string(input.HookType),
507			SessionID:  input.SessionID,
508			SessionRef: input.SessionRef,
509			Timestamp:  input.Timestamp.Format(time.RFC3339),
510			UserPrompt: input.UserPrompt,
511			ToolName:   input.ToolName,
512			ToolUseID:  input.ToolUseID,
513			ToolInput:  input.ToolInput,
514			RawData:    input.RawData,
515		}
516		data, err := json.Marshal(j)
517		if err != nil {
518			return nil, fmt.Errorf("marshal hook input: %w", err)
519		}
520		return data, nil
521	}
