523	func marshalAgentSession(s *agent.AgentSession) ([]byte, error) {
524		j := AgentSessionJSON{
525			SessionID:     s.SessionID,
526			AgentName:     string(s.AgentName),
527			RepoPath:      s.RepoPath,
528			SessionRef:    s.SessionRef,
529			StartTime:     s.StartTime.Format(time.RFC3339),
530			NativeData:    s.NativeData,
531			ModifiedFiles: s.ModifiedFiles,
532			NewFiles:      s.NewFiles,
533			DeletedFiles:  s.DeletedFiles,
534		}
535		data, err := json.Marshal(j)
536		if err != nil {
537			return nil, fmt.Errorf("marshal agent session: %w", err)
538		}
539		return data, nil
540	}
541	
542	func unmarshalAgentSession(j *AgentSessionJSON) (*agent.AgentSession, error) {
543		var startTime time.Time
544		if j.StartTime != "" {
545			var err error
546			startTime, err = time.Parse(time.RFC3339, j.StartTime)
547			if err != nil {
548				return nil, fmt.Errorf("invalid start_time: %w", err)
549			}
550		}
551		return &agent.AgentSession{
552			SessionID:     j.SessionID,
553			AgentName:     types.AgentName(j.AgentName),
554			RepoPath:      j.RepoPath,
555			SessionRef:    j.SessionRef,
556			StartTime:     startTime,
557			NativeData:    j.NativeData,
558			ModifiedFiles: j.ModifiedFiles,
559			NewFiles:      j.NewFiles,
560			DeletedFiles:  j.DeletedFiles,
561		}, nil
562	}
