564	func convertTokenUsage(r *TokenUsageResponse) *agent.TokenUsage {
565		if r == nil {
566			return nil
567		}
568		usage := &agent.TokenUsage{
569			InputTokens:         r.InputTokens,
570			CacheCreationTokens: r.CacheCreationTokens,
571			CacheReadTokens:     r.CacheReadTokens,
572			OutputTokens:        r.OutputTokens,
573			APICallCount:        r.APICallCount,
574		}
575		if r.SubagentTokens != nil {
576			usage.SubagentTokens = convertTokenUsage(r.SubagentTokens)
577		}
578		return usage
579	}
