// asExitError unwraps to *exec.ExitError without bringing in errors.As just
// to keep the test imports tight.
func asExitError(err error, target **exec.ExitError) bool {
	for cur := err; cur != nil; {
		if e, ok := cur.(*exec.ExitError); ok {
			*target = e
			return true
		}
		type unwrapper interface{ Unwrap() error }
		if u, ok := cur.(unwrapper); ok {
			cur = u.Unwrap()
		} else {
			return false
		}
	}
	return false
}

