func TestPluginDispatch_SigintReachesPlugin(t *testing.T) {
	t.Parallel()
	if runtime.GOOS == "windows" {
		t.Skip("SIGINT semantics tested on Unix only")
	}
	dir := t.TempDir()
	signalFile := filepath.Join(dir, "got-sigint.txt")
	// Plugin traps SIGINT, marks a file, and exits with a recognizable code.
	// If the parent killed it forcibly (SIGKILL) we'd see no marker file
	// and a different exit pattern.
	body := fmt.Sprintf(
		"#!/bin/sh\ntrap 'echo trapped > %q; exit 130' INT\n"+
			"# Loop with short sleeps so SIGINT can interrupt sleep promptly.\n"+
			"i=0\nwhile [ $i -lt 50 ]; do sleep 0.1; i=$((i+1)); done\nexit 0\n",
		signalFile,
	)
	if err := os.WriteFile(filepath.Join(dir, "entire-trapint"), []byte(body), 0o755); err != nil { //nolint:gosec // test fixture
		t.Fatalf("write plugin: %v", err)
	}

	cmd := exec.Command(getTestBinary(), "trapint")
	cmd.Env = pathWith(dir)
	cmd.Stdout = &bytes.Buffer{}
	cmd.Stderr = &bytes.Buffer{}
	// Put parent + child in their own process group so we can signal the
	// whole group without disturbing the test runner.
	setNewProcessGroup(cmd)

	if err := cmd.Start(); err != nil {
		t.Fatalf("start: %v", err)
	}

	// Give the plugin time to install the trap before signalling.
	waitForFile(t, signalFile, false, 100, 50)
	signalProcessGroup(t, cmd, os.Interrupt)

	// Plugin should observe the trap and write the marker.
	waitForFile(t, signalFile, true, 200, 50)

	_ = cmd.Wait()
	contents, err := os.ReadFile(signalFile)
	if err != nil {
		t.Fatalf("plugin never observed SIGINT (%v); marker file missing", err)
	}
	if got := strings.TrimSpace(string(contents)); got != "trapped" {
		t.Errorf("marker = %q, want %q", got, "trapped")
	}
}

