//go:build integration && !windows

package integration

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"syscall"
	"testing"
	"time"
)

// TestPluginDispatch_SigintReachesPlugin asserts that when the parent CLI
// receives SIGINT, the running plugin gets a chance to handle it (rather
// than being SIGKILL'd). The contract: runPlugin uses CommandContext with a
// custom Cancel that sends SIGINT, plus terminal SIGINT reaches the child
// directly via the shared process group. Either path getting the signal to
// the child is acceptable; both being missing is the regression we guard.
func TestPluginDispatch_SigintReachesPlugin(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	signalFile := filepath.Join(dir, "got-sigint.txt")

	// The plugin installs a SIGINT trap that writes a marker and exits 130
	// (conventional shell exit for SIGINT). It then loops with short sleeps
	// so the trap can fire promptly. Without a working signal path the
	// parent context cancel would eventually SIGKILL after WaitDelay and
	// no marker would be written.
	body := fmt.Sprintf(
		"#!/bin/sh\ntrap 'echo trapped > %q; exit 130' INT\n"+
			"i=0\nwhile [ $i -lt 50 ]; do sleep 0.1; i=$((i+1)); done\nexit 0\n",
		signalFile,
	)
	if err := os.WriteFile(filepath.Join(dir, "entire-trapint"), []byte(body), 0o755); err != nil { //nolint:gosec // test fixture
		t.Fatalf("write plugin: %v", err)
	}

	cmd := exec.Command(getTestBinary(), "trapint")
	cmd.Env = pathWith(dir)
	cmd.Stdout = &bytes.Buffer{}
	cmd.Stderr = &bytes.Buffer{}
	// Put parent + child in their own process group so we can target the
	// group with kill(2) without disturbing the test runner. Note: this
	// means the terminal-foreground signal path doesn't apply here — the
	// only way the plugin learns about SIGINT in this test is via the
	// parent's context-cancel handler invoking exec.Cmd.Cancel.
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}

	if err := cmd.Start(); err != nil {
		t.Fatalf("start: %v", err)
	}
	// Give the plugin a moment to install its trap before signaling.
	time.Sleep(150 * time.Millisecond)

	// SIGINT only the parent (negative pid kills the group; here we want
	// just the parent so that the child must learn about it through the
	// dispatcher's context-cancel path).
	if err := cmd.Process.Signal(os.Interrupt); err != nil {
		t.Fatalf("signal parent: %v", err)
	}

	// Wait up to 5s for the plugin to write its marker. cmd.WaitDelay in
	// runPlugin caps the parent's grace at 5s; in practice this should
	// resolve well under a second.
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		if _, err := os.Stat(signalFile); err == nil {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	_ = cmd.Wait()

	contents, err := os.ReadFile(signalFile)
	if err != nil {
		t.Fatalf("plugin never observed SIGINT — marker missing: %v", err)
	}
	if got := strings.TrimSpace(string(contents)); got != "trapped" {
		t.Errorf("marker = %q, want %q", got, "trapped")
	}
}

